mapper.select:
SELECT photo_mst.account_no AS accountNo, account.account_id AS accountId, account.account_name AS accountName, photo_mst.photo_no AS photoNo, photo_mst.photo_japanese_title AS photoJapaneseTitle, photo_mst.image_file_path AS imageFilePath, photo_mst.is_hidden_by_admin AS isHiddenByAdmin, photo_mst.created_at AS createdAt FROM photo.photo_mst photo_mst INNER JOIN common.account account ON account.account_no = photo_mst.account_no
photo_mst.is_deleted = false
AND account.account_id = #{accountId}
AND photo_mst.is_hidden_by_admin = #{isHiddenByAdmin}
ORDER BY photo_mst.created_at DESC, photo_mst.account_no ASC, photo_mst.photo_no DESC LIMIT #{limit} OFFSET #{offset}
